/**
 * Type coercion and validation utilities
 */
export class TypeUtils {
    /**
     * Coerce value to number
     */
    static coerceToNumber(value: any, strict?: boolean): number | null;
    /**
     * Coerce value to string
     */
    static coerceToString(value: any, strict?: boolean): string | null;
    /**
     * Coerce value to boolean
     */
    static coerceToBoolean(value: any, strict?: boolean): boolean | null;
    /**
     * Check equality with optional strict mode
     */
    static isEqual(left: any, right: any, strict?: boolean): boolean;
    /**
     * Type checking utilities
     */
    static isArray(value: any): value is any[];
    static isObject(value: any): boolean;
    static isString(value: any): value is string;
    static isNumber(value: any): boolean;
    static isBoolean(value: any): value is boolean;
    static isNull(value: any): boolean;
}
